Think: Process raw_listing.txt to normalize paths, resolve symlink targets (logging unresolved links), filter to regular files (including symlinks that resolve to regular files), deduplicate, and save to temp_var_inventory/file_list.txt while appending any new errors to temp_var_inventory/errors.log.

Act: bash

```bash
awk '{
  t = substr($0,1,1);
  path = substr($0,3);
  if (t == "f") {
    cmd = "readlink -f \"" path "\"";
    if ((cmd | getline real) > 0) { print real; close(cmd) } else { print "UNRESOLVED_NORMALIZE_F: " path >> "temp_var_inventory/errors.log"; close(cmd) }
  } else if (t == "l") {
    cmd = "readlink -f \"" path "\"";
    if ((cmd | getline target) > 0) {
      close(cmd);
      testcmd = "test -f \"" target "\"";
      status = system(testcmd);
      if (status == 0) print target;
      else print "SYMLINK_TARGET_NOT_REG_FILE: " path " -> " target >> "temp_var_inventory/errors.log";
    } else {
      print "UNRESOLVED_SYMLINK: " path >> "temp_var_inventory/errors.log";
      close(cmd);
    }
  }
}' temp_var_inventory/raw_listing.txt | sort -u > temp_var_inventory/file_list.txt
```

