Think: Parse temp_cpu_check/raw_cpu_info.txt to extract all candidate CPU counts (from /proc/cpuinfo, lscpu, nproc, and /sys/.../online), normalize them, add reconciliation notes, and mark a primary candidate source; write the results to temp_cpu_check/cpu_count_candidates.txt.

Act: bash

```bash
awk '
BEGIN{in_lscpu=0; in_proc=0; in_nproc=0; in_online=0; proc_processors=0; lscpu=""; nproc=""; online=""}
/^=== lscpu ===/{in_lscpu=1; in_proc=0; in_nproc=0; in_online=0; next}
/^=== \/proc\/cpuinfo ===/{in_proc=1; in_lscpu=0; in_nproc=0; in_online=0; next}
/^=== nproc ===/{in_nproc=1; in_proc=0; in_lscpu=0; in_online=0; next}
/^=== \/sys\/devices\/system\/cpu\/online ===/{in_online=1; in_lscpu=0; in_proc=0; in_nproc=0; next}
/^=== /{in_lscpu=in_proc=in_nproc=in_online=0; next}
{
 if(in_lscpu && $0 ~ /^CPU\\(s\\):/) {split($0,a,/:/); gsub(/^[ \t]+/,"",a[2]); lscpu=a[2]}
 if(in_proc && $0 ~ /^processor[ \t]*:/) proc_processors++
 if(in_nproc) { if ($0 ~ /[0-9]+/) { gsub(/^[ \t]+|[ \t]+$/,"",$0); nproc=$0 } }
 if(in_online) { gsub(/^[ \t]+|[ \t]+$/,"",$0); online=$0 }
}
END{
 print "Candidates:";
 if(proc_processors) print "processor_count_in_/proc/cpuinfo: " proc_processors;
 if(lscpu != "") print "lscpu_CPU(s): " lscpu;
 if(nproc != "") print "nproc: " nproc;
 if(online != "") print "/sys/devices/system/cpu/online: " online;
 # compute expanded online count, if available
 online_expanded_count=0;
 if(online != "") {
   s=online;
   gsub(/ /,"",s);
   split(s,parts,",");
   for(i=1;i<=length(parts);i++){
     part=parts[i];
     if(part ~ /-/){
       split(part,range,"-");
       start=range[1]+0; end=range[2]+0;
       if(end>=start) online_expanded_count += (end-start+1);
     } else if(part ~ /[0-9]+/) {
       online_expanded_count++;
     }
   }
   if(online_expanded_count>0) print "online_expanded_count: " online_expanded_count;
 }
 print "\nReconciliation notes:";
 print "- Prefer runtime online count (online_expanded_count) if present; it reflects CPUs currently online.";
 print "- nproc reports available processing units to the current user.";
 print "- lscpu CPU(s) is the system-level configured logical CPUs.";
 print "- /proc/cpuinfo processor entries show logical processors recognized by the kernel.";
 print "\nPrimary candidate selection logic:";
 print "- Preference order: online_expanded_count, nproc, lscpu_CPU(s), /proc/cpuinfo processor count.";
 primary="unknown";
 if(online_expanded_count>0) primary="online_expanded_count";
 else if(nproc != "") primary="nproc";
 else if(lscpu != "") primary="lscpu_CPU(s)";
 else if(proc_processors>0) primary="processor_count_in_/proc/cpuinfo";
 print "Primary candidate source: " primary;
 print "\nNotes on potential conflicts:";
 print "- If online_expanded_count differs from nproc or lscpu, this may indicate hotplugged CPUs, cpuset/cgroups limiting, or virtualization constraints.";
 print "- If /proc/cpuinfo processor count differs from lscpu or nproc, check for offline CPUs or kernel visibility issues.";
}' temp_cpu_check/raw_cpu_info.txt > temp_cpu_check/cpu_count_candidates.txt
```

